std::vector<std::unique_ptr<ChooserContextBase::Object>> GetGrantedObjects(
    const GURL& requesting_origin,
    const GURL& embedding_origin) {
  std::vector<std::unique_ptr<ChooserContextBase::Object>> results;

  // Check if origins are valid.
  if (!requesting_origin.is_valid() || !embedding_origin.is_valid()) {
    return results;
  }

  // Check if permission can be granted.
  bool permission_granted = CheckPermission(requesting_origin, embedding_origin);
  if (!permission_granted) {
    return results;
  }

  // Retrieve website settings and extract the object list.
  WebsiteSettings settings = GetWebsiteSettings(requesting_origin);
  std::vector<ChooserContextBase::Object> object_list = settings.GetObjectList();

  // Check each object and add to results if valid.
  for (const auto& obj : object_list) {
    if (obj.IsValid()) {
      results.push_back(std::make_unique<ChooserContextBase::Object>(obj));
    }
  }

  return results;
}

